(2974222, 417415, 15711, '<td valign="top">ha ha Love her fun expression. That''s some wind!!</td>', 'ha ha Love her fun expression. That''s some wind!!', '2006-10-30 00:11:51.000000', NULL, 1),
(2974226, 418842, 29906, '<td valign="top">Awesome shot, I am not sure about the background color though, 9</td>', 'Awesome shot, I am not sure about the background color though, 9', '2006-10-30 00:12:45.000000', NULL, 1),
(2974227, 419254, 15711, '<td valign="top">Nice backlit image. Love the bokeh. Her eyes are beautiful. I hope people see enough "wind" in it to score it high. I''d crop just above the knots in her straps.</td>', 'Nice backlit image. Love the bokeh. Her eyes are beautiful. I hope people see enough "wind" in it to score it high. I''d crop just above the knots in her straps.', '2006-10-30 00:12:51.000000', NULL, 1),
(2974240, 418417, 15711, '<td valign="top">Awesome DOF. Love that single focused eye. My only critique is maybe to adjust contrast a smidge to intensify the diff. levels of tonality.</td>', 'Awesome DOF. Love that single focused eye. My only critique is maybe to adjust contrast a smidge to intensify the diff. levels of tonality.', '2006-10-30 00:14:14.000000', NULL, 1),
(2974241, 417172, 29906, '<td valign="top">Best flag shot so far.</td>', 'Best flag shot so far.', '2006-10-30 00:14:17.000000', NULL, 1),
(2974246, 418630, 15711, '<td valign="top">I love her expression.  The peachy and red tones are great with the black and green.</td>', 'I love her expression.  The peachy and red tones are great with the black and green.', '2006-10-30 00:15:04.000000', NULL, 1),
(2974249, 418571, 15711, '<td valign="top">CUTE!! Love the blue tones.  Great expression.</td>', 'CUTE!! Love the blue tones.  Great expression.', '2006-10-30 00:15:44.000000', NULL, 1),
(2974252, 417172, 66515, '<td valign="top">I knew there would be lots of flags in this challenge and for the most part they are unremarkable. This one is pretty good. I have to ask though, why wouldn''t you do a quick flip to get the proper orientation for the flag?</td>', 'I knew there would be lots of flags in this challenge and for the most part they are unremarkable. This one is pretty good. I have to ask though, why wouldn''t you do a quick flip to get the proper orientation for the flag?', '2006-10-30 00:16:05.000000', NULL, 1),
(2974257, 418871, 66515, '<td valign="top">Great idea and well executed. (I am wishing now that I did something like this)</td>', 'Great idea and well executed. (I am wishing now that I did something like this)', '2006-10-30 00:16:45.000000', NULL, 1),
(2974264, 419300, 15711, '<td valign="top">Very cool. This has an abstract aetherial quality. It might be a bit avant garde for this crowd, but I like it. Different. 7</td>', 'Very cool. This has an abstract aetherial quality. It might be a bit avant garde for this crowd, but I like it. Different. 7', '2006-10-30 00:17:27.000000', NULL, 1),
