(2974304, 418905, 15711, '<td valign="top">What a cool image. Love the title too. Nice spin on the leaf thing. The perspective and lines of the railing add a nice bit of variation and texture. 8</td>', 'What a cool image. Love the title too. Nice spin on the leaf thing. The perspective and lines of the railing add a nice bit of variation and texture. 8', '2006-10-30 00:24:23.000000', NULL, 1),
(2974315, 418521, 15711, '<td valign="top">Wow this is beautiful. I know that it''s always windy at the beach, but I''m sensing more the power of the waves than the wind here. Nonetheless, a stunning seascape. The colors, lines and composition are perfect.</td>', 'Wow this is beautiful. I know that it''s always windy at the beach, but I''m sensing more the power of the waves than the wind here. Nonetheless, a stunning seascape. The colors, lines and composition are perfect.', '2006-10-30 00:26:05.000000', NULL, 1),
(2974321, 418842, 41337, '<td valign="top">Welcome back Larus. Super visual as always but I think I like your older version of this better.</td>', 'Welcome back Larus. Super visual as always but I think I like your older version of this better.', '2006-10-30 00:27:00.000000', NULL, 1),
(2974322, 418623, 15711, '<td valign="top">Beautiful tones.  I wish she were closer in the shot. Love the blue/yellow theme going on here with the POP of black.</td>', 'Beautiful tones.  I wish she were closer in the shot. Love the blue/yellow theme going on here with the POP of black.', '2006-10-30 00:27:03.000000', NULL, 1),
