(2975979, 418341, 18552, '<td valign="top">This is a nice concept but the still leaves on the ground really give it that "obvious setup" feeling.</td>', 'This is a nice concept but the still leaves on the ground really give it that "obvious setup" feeling.', '2006-10-30 15:08:15.000000', NULL, 1),
(2975982, 419170, 66384, '<td valign="top">Now that''s windy!</td>', 'Now that''s windy!', '2006-10-30 15:09:39.000000', NULL, 1),
(2975984, 418793, 18552, '<td valign="top">This really looks windy! Very nice picture.</td>', 'This really looks windy! Very nice picture.', '2006-10-30 15:09:46.000000', NULL, 1),
