(2976005, 419298, 66384, '<td valign="top">I can feel this wind, and I love the photo.</td>', 'I can feel this wind, and I love the photo.', '2006-10-30 15:14:22.000000', NULL, 1),
(2976013, 417381, 66384, '<td valign="top">Love the shot!!! Where did you find such a place? Don''t see the wind, though.</td>', 'Love the shot!!! Where did you find such a place? Don''t see the wind, though.', '2006-10-30 15:17:29.000000', NULL, 1),
(2976022, 419295, 66384, '<td valign="top">Very abstract. Nice colors. Good idea. Makes me dizzy.</td>', 'Very abstract. Nice colors. Good idea. Makes me dizzy.', '2006-10-30 15:19:50.000000', NULL, 1),
