(2976797, 418521, 12733, '<td valign="top">Great reflections on the water.</td>', 'Great reflections on the water.', '2006-10-30 20:31:44.000000', NULL, 1),
(2976800, 418999, 51538, '<td valign="top">Reminds me of the Sussex Downs and along the River Arun.  Probably quite wrong.  But the tree bespeaks a prevailing easterly wind.  It''s a grand location for photography.</td>', 'Reminds me of the Sussex Downs and along the River Arun.  Probably quite wrong.  But the tree bespeaks a prevailing easterly wind.  It''s a grand location for photography.', '2006-10-30 20:32:50.000000', NULL, 1),
