(2977387, 418341, 66398, '<td valign="top">nice idea, nice photo and all and its in my higher scores but, I''m a little bothered by the leaves on the ground that aren''t being blown away by the huge wind.</td>', 'nice idea, nice photo and all and its in my higher scores but, I''m a little bothered by the leaves on the ground that aren''t being blown away by the huge wind.', '2006-10-30 23:34:25.000000', NULL, 1),
(2977394, 419258, 66398, '<td valign="top">nice idea, nice photo and all but, I''m a little bothered by the leaves on the ground that aren''t being blown away by the huge wind.</td>', 'nice idea, nice photo and all but, I''m a little bothered by the leaves on the ground that aren''t being blown away by the huge wind.', '2006-10-30 23:35:08.000000', NULL, 1),
