(2978358, 419300, 67578, '<td valign="top">like it</td>', 'like it', '2006-10-31 09:58:22.000000', NULL, 1),
(2978361, 419197, 30049, '<td valign="top">It''s "ok".  I think the limited range of movement for the windblown petal is making it more challenging to see "wind" in your photo.  Some motion blur via a slower shutter speed would help but would introduce it''s own set of problems to overcome (i.e. - the whole flower moving instead of just the petal).  All of the above is JMO of course.  Good luck in the challenge.</td>', 'It''s "ok".  I think the limited range of movement for the windblown petal is making it more challenging to see "wind" in your photo.  Some motion blur via a slower shutter speed would help but would introduce it''s own set of problems to overcome (i.e. - the whole flower moving instead of just the petal).  All of the above is JMO of course.  Good luck in the challenge.', '2006-10-31 09:59:53.000000', NULL, 1),
(2978362, 419344, 67578, '<td valign="top">i like it.</td>', 'i like it.', '2006-10-31 10:00:45.000000', NULL, 1),
