(2978375, 419141, 67578, '<td valign="top">pretty</td>', 'pretty', '2006-10-31 10:05:46.000000', NULL, 1),
(2978376, 419249, 30049, '<td valign="top">Show me the wind in action, not the results.  At least to score well in this challenge I think some wind motion or action taking place is needed.  JMO.  As for the technicals on this image, I like the lines created by the bg hill and the bent trees.  The cow takes away a little as it easily draws the eye over and becomes a more dominant subject.  The conversion to B/W makes sense given the sky you had to work with, although I think the tonal range is a little short (blacks could be increased).  A small dose of additional contrast would also help the image from being flat.  Best of luck to you in the challenge.</td>', 'Show me the wind in action, not the results.  At least to score well in this challenge I think some wind motion or action taking place is needed.  JMO.  As for the technicals on this image, I like the lines created by the bg hill and the bent trees.  The cow takes away a little as it easily draws the eye over and becomes a more dominant subject.  The conversion to B/W makes sense given the sky you had to work with, although I think the tonal range is a little short (blacks could be increased).  A small dose of additional contrast would also help the image from being flat.  Best of luck to you in the challenge.', '2006-10-31 10:05:46.000000', NULL, 1),
(2978380, 418623, 67578, '<td valign="top">pretty</td>', 'pretty', '2006-10-31 10:07:05.000000', NULL, 1),
