(2979214, 418435, 30049, '<td valign="top">Wow - That''s bright!  As in a whole lot of light.  :D  First impression anyway.  I like your POV used when taking this shot and the building in back adds a nice touch.  Hard to really know if it''s windy or not based on the grass being static - meaning not blurry to indicate motion or anything.  I imagine it was difficult to slow down the shutter speed enough being as bright as it is.  Anyway.  Overall, nicely done.  Best of luck to you in the challenge.</td>', 'Wow - That''s bright!  As in a whole lot of light.  :D  First impression anyway.  I like your POV used when taking this shot and the building in back adds a nice touch.  Hard to really know if it''s windy or not based on the grass being static - meaning not blurry to indicate motion or anything.  I imagine it was difficult to slow down the shutter speed enough being as bright as it is.  Anyway.  Overall, nicely done.  Best of luck to you in the challenge.', '2006-10-31 16:10:50.000000', NULL, 1),
(2979217, 419344, 30049, '<td valign="top">Yep.  Windy all right.  Looks like it was cold too!  :D  The star trails are a nice touch.  Good luck in the challenge.</td>', 'Yep.  Windy all right.  Looks like it was cold too!  :D  The star trails are a nice touch.  Good luck in the challenge.', '2006-10-31 16:12:04.000000', NULL, 1),
(2979220, 417768, 43565, '<td valign="top">I like that the trunk is in focus yet the leaves are moving.  I also like the lighting.</td>', 'I like that the trunk is in focus yet the leaves are moving.  I also like the lighting.', '2006-10-31 16:13:17.000000', NULL, 1),
(2979223, 419119, 30049, '<td valign="top">Funny.  This reminds me of an image in the ''Lighting'' challenge just completed.  Of what I''ve seen so far for water/waves type entries, I like this one the best.  Not sure about the portrait orientation (whole lot of scrolling going on), but you certainly put forth a nice effort for this challenge.  Good luck to you.</td>', 'Funny.  This reminds me of an image in the ''Lighting'' challenge just completed.  Of what I''ve seen so far for water/waves type entries, I like this one the best.  Not sure about the portrait orientation (whole lot of scrolling going on), but you certainly put forth a nice effort for this challenge.  Good luck to you.', '2006-10-31 16:14:19.000000', NULL, 1),
(2979252, 417172, 63218, '<td valign="top">the flag is displayed backwards (but the colors are good)</td>', 'the flag is displayed backwards (but the colors are good)', '2006-10-31 16:26:01.000000', NULL, 1),
(2979264, 419395, 59458, '<td valign="top">I like the shot. I think I would like it more if you could see the motion in the mills.</td>', 'I like the shot. I think I would like it more if you could see the motion in the mills.', '2006-10-31 16:29:45.000000', NULL, 1),
(2979273, 417819, 67541, '<td valign="top">Great shot, really like the color combination and it really hit the mark for "wind".</td>', 'Great shot, really like the color combination and it really hit the mark for "wind".', '2006-10-31 16:34:21.000000', NULL, 1),
(2979277, 419107, 67541, '<td valign="top">Great shot. Good job.</td>', 'Great shot. Good job.', '2006-10-31 16:35:23.000000', NULL, 1),
(2979280, 418162, 50357, '<td valign="top">I like this.  Beautiful colors, great composition, great title and nicely bordered!  10</td>', 'I like this.  Beautiful colors, great composition, great title and nicely bordered!  10', '2006-10-31 16:37:28.000000', NULL, 1),
(2979283, 418949, 50357, '<td valign="top">Very nice.  10</td>', 'Very nice.  10', '2006-10-31 16:38:21.000000', NULL, 1),
(2979284, 418871, 50357, '<td valign="top">Nice use of black and white.   9</td>', 'Nice use of black and white.   9', '2006-10-31 16:39:09.000000', NULL, 1),
(2979285, 419141, 50357, '<td valign="top">Very good!  10</td>', 'Very good!  10', '2006-10-31 16:39:39.000000', NULL, 1),
(2979289, 419254, 50357, '<td valign="top">Nicely done!  10</td>', 'Nicely done!  10', '2006-10-31 16:40:16.000000', NULL, 1),
(2979294, 418341, 50357, '<td valign="top">This is great!  10</td>', 'This is great!  10', '2006-10-31 16:41:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2979311, 418990, 48680, '<td valign="top">has the initial feel of a candid, but something in her expression makes me think not, and the nice lighting of her face also makes me think not.  i do like it, nice take on the challenge</td>', 'has the initial feel of a candid, but something in her expression makes me think not, and the nice lighting of her face also makes me think not.  i do like it, nice take on the challenge', '2006-10-31 16:49:23.000000', NULL, 1),
(2979324, 416531, 67152, '<td valign="top">I like the color cast of this one.</td>', 'I like the color cast of this one.', '2006-10-31 16:54:20.000000', NULL, 1),
(2979326, 417899, 48680, '<td valign="top">back to take another look &amp; bump up<br/>thinking it might also look good in bw too?</td>', 'back to take another look & bump upthinking it might also look good in bw too?', '2006-10-31 16:54:31.000000', NULL, 1),
(2979352, 416147, 66597, '<td valign="top">IMO this could stand a bit more saturation.</td>', 'IMO this could stand a bit more saturation.', '2006-10-31 17:04:13.000000', NULL, 1),
(2979355, 419254, 66597, '<td valign="top">Nice bokeh :-)</td>', 'Nice bokeh :-)', '2006-10-31 17:05:12.000000', NULL, 1),
(2979365, 417581, 66597, '<td valign="top">Lovely colors.</td>', 'Lovely colors.', '2006-10-31 17:09:18.000000', NULL, 1),
(2979370, 419391, 45475, '<td valign="top">Wonderful movement here. I''m so glad I came back for another look at this. What I didn''t get the first time round, was that I was looking at drops of water around the leaf. Exquisite in-camera art. I''m bumping up - 9.</td>', 'Wonderful movement here. I''m so glad I came back for another look at this. What I didn''t get the first time round, was that I was looking at drops of water around the leaf. Exquisite in-camera art. I''m bumping up - 9.', '2006-10-31 17:11:05.000000', NULL, 1),
(2979372, 418962, 66597, '<td valign="top">This is a unique capture.</td>', 'This is a unique capture.', '2006-10-31 17:12:20.000000', NULL, 1),
(2979375, 419124, 66597, '<td valign="top">This looks a little overexposed to me, though I like the wind.</td>', 'This looks a little overexposed to me, though I like the wind.', '2006-10-31 17:14:49.000000', NULL, 1),
(2979376, 419117, 66597, '<td valign="top">The colors look a bit artificial in this, but the composition is nice</td>', 'The colors look a bit artificial in this, but the composition is nice', '2006-10-31 17:14:55.000000', NULL, 1),
(2979378, 417867, 66597, '<td valign="top">I really like this, though the blown out lights on the left of fountain are a bit distracting.</td>', 'I really like this, though the blown out lights on the left of fountain are a bit distracting.', '2006-10-31 17:15:05.000000', NULL, 1),
(2979402, 419339, 49378, '<td valign="top">Really nice!</td>', 'Really nice!', '2006-10-31 17:31:17.000000', NULL, 1),
(2979479, 417041, 33068, '<td valign="top">Now that is some wicked fun processing.  Would love to learn how to do this.  WELL DONE!</td>', 'Now that is some wicked fun processing.  Would love to learn how to do this.  WELL DONE!', '2006-10-31 18:00:17.000000', NULL, 1),
(2979502, 418571, 10943, '<td valign="top">Great colors!  Nice concept too.  I hope this one does well.</td>', 'Great colors!  Nice concept too.  I hope this one does well.', '2006-10-31 18:10:33.000000', NULL, 1),
(2979583, 417768, 29011, '<td valign="top">This looks great. It has this fairy tale mood to it. A simple subject such as a tree which looks quite surreal now.</td>', 'This looks great. It has this fairy tale mood to it. A simple subject such as a tree which looks quite surreal now.', '2006-10-31 18:51:35.000000', NULL, 1),
(2979592, 418623, 29011, '<td valign="top">Beautiful sunset colors here. Interesting that the veil''s coloring is similar ;) that''s a neat touch alright. But the light on the model is a bit too harsh , perhaps if it was toned down just a bit? Also find the rocks distracting and with them out of the way, would''ve liked the model''s head to look out but have the hands in the same position.  Still, a fine shot it is.</td>', 'Beautiful sunset colors here. Interesting that the veil''s coloring is similar ;) that''s a neat touch alright. But the light on the model is a bit too harsh , perhaps if it was toned down just a bit? Also find the rocks distracting and with them out of the way, would''ve liked the model''s head to look out but have the hands in the same position.  Still, a fine shot it is.', '2006-10-31 18:57:08.000000', NULL, 1),
(2979593, 417768, 45475, '<td valign="top">Way cool shot. My second visit and am bumping - 8.</td>', 'Way cool shot. My second visit and am bumping - 8.', '2006-10-31 18:57:15.000000', NULL, 1),
(2979594, 417415, 29011, '<td valign="top">Woah indeed :) This is the funnest wind blown hair portrait of the bunch.</td>', 'Woah indeed :) This is the funnest wind blown hair portrait of the bunch.', '2006-10-31 18:58:19.000000', NULL, 1),
(2979598, 419395, 29011, '<td valign="top">Very nicely composed image and nice toning. Wonder if it was possible to get some motion blur in them rotors via a longer exposure?</td>', 'Very nicely composed image and nice toning. Wonder if it was possible to get some motion blur in them rotors via a longer exposure?', '2006-10-31 18:59:48.000000', NULL, 1),
(2979602, 418966, 29011, '<td valign="top">Really like the whole look of the photo. Great job with the exposure and PP. Pitty it''s cropped so tightly. Was it possible to zoom out or move back some more? so the shed wasn''t cut off.</td>', 'Really like the whole look of the photo. Great job with the exposure and PP. Pitty it''s cropped so tightly. Was it possible to zoom out or move back some more? so the shed wasn''t cut off.', '2006-10-31 19:02:44.000000', NULL, 1),
(2979613, 418521, 29011, '<td valign="top">A wonderful all around shot, looks really great. Doesn''t particullary speak wind to me, the sky looks like storm has already passed but the surf is rough though.</td>', 'A wonderful all around shot, looks really great. Doesn''t particullary speak wind to me, the sky looks like storm has already passed but the surf is rough though.', '2006-10-31 19:10:12.000000', NULL, 1),
(2979616, 418574, 50695, '<td valign="top">wonderful gritty feel to this. there''s dust in the wind!</td>', 'wonderful gritty feel to this. there''s dust in the wind!', '2006-10-31 19:11:31.000000', NULL, 1),
(2979625, 418689, 29011, '<td valign="top">Easily my favorite landscape of the challenge. The b/w toning looks great and so does the composition. Good luck with this one!</td>', 'Easily my favorite landscape of the challenge. The b/w toning looks great and so does the composition. Good luck with this one!', '2006-10-31 19:14:21.000000', NULL, 1),
(2979626, 419300, 45475, '<td valign="top">Perfectly absurd... and wonderful. Bumping.</td>', 'Perfectly absurd... and wonderful. Bumping.', '2006-10-31 19:14:55.000000', NULL, 1),
(2979635, 419113, 45475, '<td valign="top">Nice work. I like that the ribbons are blurred to the point of looking like smoke. Well done :)</td>', 'Nice work. I like that the ribbons are blurred to the point of looking like smoke. Well done :)', '2006-10-31 19:16:48.000000', NULL, 1),
(2979642, 418630, 29011, '<td valign="top">Now that''s wind! The best overall windy hair potrait of the bunch. Combining good technicals with good wind. A very nice choice of location too.</td>', 'Now that''s wind! The best overall windy hair potrait of the bunch. Combining good technicals with good wind. A very nice choice of location too.', '2006-10-31 19:19:48.000000', NULL, 1),
(2979646, 418842, 29011, '<td valign="top">Splendid portrait. Could''ve used just a little more wind though, so the hair in the back got more movement.</td>', 'Splendid portrait. Could''ve used just a little more wind though, so the hair in the back got more movement.', '2006-10-31 19:21:20.000000', NULL, 1),
(2979666, 417041, 50695, '<td valign="top">that left leg is looking a bit ogrish... otherwise a fun shot.</td>', 'that left leg is looking a bit ogrish... otherwise a fun shot.', '2006-10-31 19:30:15.000000', NULL, 1),
(2979669, 417592, 50695, '<td valign="top">I think you should try black and white for this.</td>', 'I think you should try black and white for this.', '2006-10-31 19:31:10.000000', NULL, 1),
(2979678, 417867, 30982, '<td valign="top">I do see the spray as the wind is distorting it and I like the silhouette effect with just barely being able to see the person on the right.  Composition is nice and the backlighting is very effective.  It may not be the strongest for displaying "wind" - more of a good shot to depict backlighting.</td>', 'I do see the spray as the wind is distorting it and I like the silhouette effect with just barely being able to see the person on the right.  Composition is nice and the backlighting is very effective.  It may not be the strongest for displaying "wind" - more of a good shot to depict backlighting.', '2006-10-31 19:34:23.000000', NULL, 1),
(2979680, 418521, 50695, '<td valign="top">ok, this is my third prediction for a ribbon. let''s see if I''m right.</td>', 'ok, this is my third prediction for a ribbon. let''s see if I''m right.', '2006-10-31 19:34:42.000000', NULL, 1),
(2979684, 418869, 30982, '<td valign="top">Good job catching the leaves in motion and conveying that.  My only nit is I''m not sure I like how far up the frame the car is.</td>', 'Good job catching the leaves in motion and conveying that.  My only nit is I''m not sure I like how far up the frame the car is.', '2006-10-31 19:35:36.000000', NULL, 1),
(2979685, 418842, 61313, '<td valign="top">Great Image, Best I''ve seen. 1st place</td>', 'Great Image, Best I''ve seen. 1st place', '2006-10-31 19:35:39.000000', NULL, 1),
(2979688, 417692, 30982, '<td valign="top">Wonderful detail on the bird.  Wind is implied - or at least air is implied!</td>', 'Wonderful detail on the bird.  Wind is implied - or at least air is implied!', '2006-10-31 19:36:16.000000', NULL, 1),
(2979702, 419003, 30982, '<td valign="top">Nice job catching on in midair!  Maybe just a touch too much or not enough negative space - just seems a tad out of balance to me, but that''s a personal preference.</td>', 'Nice job catching on in midair!  Maybe just a touch too much or not enough negative space - just seems a tad out of balance to me, but that''s a personal preference.', '2006-10-31 19:38:53.000000', NULL, 1),
(2979708, 418453, 30982, '<td valign="top">I think this is supposed to be depicting the effect of a serious headwind?  Takes some interpretation on the viewer''s part.</td>', 'I think this is supposed to be depicting the effect of a serious headwind?  Takes some interpretation on the viewer''s part.', '2006-10-31 19:39:38.000000', NULL, 1),
(2979712, 419050, 30982, '<td valign="top">Lovely abstract - colors are very nice.  Only thing I''d suggest to better depict "wind" vice camera movement is to have a few of the trunks more clearly focused.  I do like this the way it is, though.</td>', 'Lovely abstract - colors are very nice.  Only thing I''d suggest to better depict "wind" vice camera movement is to have a few of the trunks more clearly focused.  I do like this the way it is, though.', '2006-10-31 19:40:33.000000', NULL, 1),
(2979719, 418867, 30982, '<td valign="top">The depicts wind quite well!  Colors are nicely muted, which I like against the strong green of the pines.</td>', 'The depicts wind quite well!  Colors are nicely muted, which I like against the strong green of the pines.', '2006-10-31 19:42:11.000000', NULL, 1),
(2979725, 417867, 50695, '<td valign="top">Excellent. Fantastic. Perfect. Instant 10. Wow. You have the gift. Things that would be a mistake in anyone else''s photograph are as inevitable as wind in yours. Bravo.</td>', 'Excellent. Fantastic. Perfect. Instant 10. Wow. You have the gift. Things that would be a mistake in anyone else''s photograph are as inevitable as wind in yours. Bravo.', '2006-10-31 19:44:10.000000', NULL, 1),
(2979730, 419249, 50695, '<td valign="top">I cannot believe how many brilliant pictures I am seeing in this challenge. It is starting to freak me out. Another fave, another 10.</td>', 'I cannot believe how many brilliant pictures I am seeing in this challenge. It is starting to freak me out. Another fave, another 10.', '2006-10-31 19:45:00.000000', NULL, 1),
(2979732, 417320, 50695, '<td valign="top">Wow. The first picture I look at and I''m blown away, so to speak. I''m going to give you a 9 now and then bump you up to a 10 later.</td>', 'Wow. The first picture I look at and I''m blown away, so to speak. I''m going to give you a 9 now and then bump you up to a 10 later.', '2006-10-31 19:45:20.000000', NULL, 1),
(2979733, 419298, 50695, '<td valign="top">somehow I can feel the wind in this photo. Amazing.</td>', 'somehow I can feel the wind in this photo. Amazing.', '2006-10-31 19:45:28.000000', NULL, 1),
(2979737, 417618, 30982, '<td valign="top">Depicts a coastal breeze very nicely - I like the color on her dress against the nearly colorless background - subtle and quite lovely.</td>', 'Depicts a coastal breeze very nicely - I like the color on her dress against the nearly colorless background - subtle and quite lovely.', '2006-10-31 19:46:20.000000', NULL, 1),
(2979738, 417415, 30982, '<td valign="top">Very fun capture, and definitely shows the effects of wind!</td>', 'Very fun capture, and definitely shows the effects of wind!', '2006-10-31 19:46:45.000000', NULL, 1),
(2979742, 418866, 30982, '<td valign="top">Pretty good depiction of the effects of wind, though the little seeds blend into the background a bit.  I''m not particularly fond of the border - I don''t normally comment on borders unless I think they distract from the presentation.  A simple thin black border might have been more effective, but I also realize it''s a matter of personal taste.</td>', 'Pretty good depiction of the effects of wind, though the little seeds blend into the background a bit.  I''m not particularly fond of the border - I don''t normally comment on borders unless I think they distract from the presentation.  A simple thin black border might have been more effective, but I also realize it''s a matter of personal taste.', '2006-10-31 19:48:12.000000', NULL, 1),
(2979804, 416531, 30982, '<td valign="top">"Wind" isn''t the first thing that enters my mind when I see this - the coming of winter is - but with the coming of winter comes wind, cold and blustery.  The visible effect on the stalks emphasizes this.  I love the lines of the fence and the echo of those lines from the fence in the distance.  The toning is excellent.</td>', '"Wind" isn''t the first thing that enters my mind when I see this - the coming of winter is - but with the coming of winter comes wind, cold and blustery.  The visible effect on the stalks emphasizes this.  I love the lines of the fence and the echo of those lines from the fence in the distance.  The toning is excellent.', '2006-10-31 20:02:12.000000', NULL, 1),
(2979810, 419327, 30982, '<td valign="top">I can see where you''re aiming at the effects that wind have had on the sculpted rock - though water has played a large part, too, I might add.  The dead calm water belies any current presence of wind, which I think might result in some lower scores on this one.  I do like the black and white treatment used here.</td>', 'I can see where you''re aiming at the effects that wind have had on the sculpted rock - though water has played a large part, too, I might add.  The dead calm water belies any current presence of wind, which I think might result in some lower scores on this one.  I do like the black and white treatment used here.', '2006-10-31 20:03:56.000000', NULL, 1),
(2979815, 419197, 139, '<td valign="top">I like the idea, but it feels forced.  Maybe a lower angle would better express the shape of the flower.</td>', 'I like the idea, but it feels forced.  Maybe a lower angle would better express the shape of the flower.', '2006-10-31 20:04:51.000000', NULL, 1),
(2979819, 417592, 30982, '<td valign="top">LOL!  Definitely a good depiction of wind.  As a photograph, it''s a little bland.  Perhaps a more unusual angle or having the paper less in the center of the shot would add some interest.  Lighting seems pretty even, though the paper itself has a sort of blue cast to it.</td>', 'LOL!  Definitely a good depiction of wind.  As a photograph, it''s a little bland.  Perhaps a more unusual angle or having the paper less in the center of the shot would add some interest.  Lighting seems pretty even, though the paper itself has a sort of blue cast to it.', '2006-10-31 20:05:26.000000', NULL, 1),
(2979824, 419382, 30982, '<td valign="top">Love the red toning on this and really like the way you''ve framed the blowing hair in the whiter section of the sky.</td>', 'Love the red toning on this and really like the way you''ve framed the blowing hair in the whiter section of the sky.', '2006-10-31 20:06:09.000000', NULL, 1),
(2979831, 419254, 139, '<td valign="top">The lone strands of hair across her face are distracting -- If this is a Wind photo I really want to see a lot more Wind.  The wind just comes across here as a distracting element in an otherwise nice picture of a girl rather than an element of the photo itself.  I also don''t really like the composition, I''d put the girl more to the right.</td>', 'The lone strands of hair across her face are distracting -- If this is a Wind photo I really want to see a lot more Wind.  The wind just comes across here as a distracting element in an otherwise nice picture of a girl rather than an element of the photo itself.  I also don''t really like the composition, I''d put the girl more to the right.', '2006-10-31 20:07:26.000000', NULL, 1),
(2979837, 418990, 30982, '<td valign="top">She looks quite warm despite what looks to be a chilly breeze blowing her scarf.</td>', 'She looks quite warm despite what looks to be a chilly breeze blowing her scarf.', '2006-10-31 20:08:02.000000', NULL, 1),
(2979840, 419361, 139, '<td valign="top">Lower angle, prehaps, and less light in the middle of the car?</td>', 'Lower angle, prehaps, and less light in the middle of the car?', '2006-10-31 20:08:37.000000', NULL, 1),
(2979841, 418815, 30982, '<td valign="top">A fun shot - I like the blurred leaves that leave just enough of her face and smile.</td>', 'A fun shot - I like the blurred leaves that leave just enough of her face and smile.', '2006-10-31 20:08:52.000000', NULL, 1),
(2979850, 416147, 30982, '<td valign="top">An effective depiction of the effects of wind, and sadly, litter.  Love the red of the barn in the distance.  As for composition, some may feel the horizon too "centered" though to cut off the sky (which isn''t contributing as much to the shot as the foreground) cuts off the top of the closest pole, which may be undesirable.</td>', 'An effective depiction of the effects of wind, and sadly, litter.  Love the red of the barn in the distance.  As for composition, some may feel the horizon too "centered" though to cut off the sky (which isn''t contributing as much to the shot as the foreground) cuts off the top of the closest pole, which may be undesirable.', '2006-10-31 20:10:56.000000', NULL, 1),
(2979854, 418966, 30982, '<td valign="top">Very nice - the tilt may be considered a bit disconcerting as it seems opposed in direction to that of the wind, but quite strongly emphasizes the power of wind, in a way.</td>', 'Very nice - the tilt may be considered a bit disconcerting as it seems opposed in direction to that of the wind, but quite strongly emphasizes the power of wind, in a way.', '2006-10-31 20:12:29.000000', NULL, 1),
(2979856, 419204, 139, '<td valign="top">This is a nice picture, but I am not drawn to the windblown leaves.  I am drawn to the stream, then the rocks, then the trees, but not to the leaves.</td>', 'This is a nice picture, but I am not drawn to the windblown leaves.  I am drawn to the stream, then the rocks, then the trees, but not to the leaves.', '2006-10-31 20:12:51.000000', NULL, 1),
(2979858, 418891, 30982, '<td valign="top">Brrr.  Cold just looking at it!  Nice tonal range in difficult conditions.</td>', 'Brrr.  Cold just looking at it!  Nice tonal range in difficult conditions.', '2006-10-31 20:13:07.000000', NULL, 1),
(2979862, 419171, 30982, '<td valign="top">An excellent way to depict a breeze.</td>', 'An excellent way to depict a breeze.', '2006-10-31 20:13:52.000000', NULL, 1),
(2979873, 417415, 139, '<td valign="top">Excellent!  I love almost everything about this photo... The guy in the background is obviously distracting, though, and I would consider cropping it differently if possible, as she is in an awkward position in the frame.</td>', 'Excellent!  I love almost everything about this photo... The guy in the background is obviously distracting, though, and I would consider cropping it differently if possible, as she is in an awkward position in the frame.', '2006-10-31 20:16:27.000000', NULL, 1),
(2979881, 418815, 139, '<td valign="top">Ah, finally one with blurry leaves that has something for me to focus on!  Excellent photo.</td>', 'Ah, finally one with blurry leaves that has something for me to focus on!  Excellent photo.', '2006-10-31 20:18:02.000000', NULL, 1),
(2979960, 418770, 63218, '<td valign="top">your flag is displayed backwards, the stars should be on the L</td>', 'your flag is displayed backwards, the stars should be on the L', '2006-10-31 20:35:36.000000', NULL, 1),
(2979985, 419303, 30982, '<td valign="top">Interesting, but for some reason I have problems with the flame and wick flying off the candle.  Still, clearly depicts wind!</td>', 'Interesting, but for some reason I have problems with the flame and wick flying off the candle.  Still, clearly depicts wind!', '2006-10-31 20:46:38.000000', NULL, 1),
(2979988, 419194, 30982, '<td valign="top">Nice take - good exposure and color in the flame, good timing.  Might have been interesting to have the match heads ascending in height.</td>', 'Nice take - good exposure and color in the flame, good timing.  Might have been interesting to have the match heads ascending in height.', '2006-10-31 20:48:09.000000', NULL, 1),
(2979990, 419066, 53243, '<td valign="top">The birds are very beautiful, but I''m not sure it depicts wind - it seems to be more of flight.</td>', 'The birds are very beautiful, but I''m not sure it depicts wind - it seems to be more of flight.', '2006-10-31 20:48:43.000000', NULL, 1),
