(2980294, 418304, 30982, '<td valign="top">The mist off the waves would indicate the presence of a brisk breeze.  I like the contrast of the orangish sand tones to the gray of the water.</td>', 'The mist off the waves would indicate the presence of a brisk breeze.  I like the contrast of the orangish sand tones to the gray of the water.', '2006-10-31 22:20:24.000000', NULL, 1),
(2980297, 418795, 67553, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2006-10-31 22:20:29.000000', NULL, 1),
(2980299, 418823, 30982, '<td valign="top">Very nice!  Composition works well with the pile of leaves semi-defined backed by the lines of whatever it is they''re on.  The few in motion are a wonderful touch.</td>', 'Very nice!  Composition works well with the pile of leaves semi-defined backed by the lines of whatever it is they''re on.  The few in motion are a wonderful touch.', '2006-10-31 22:21:31.000000', NULL, 1),
