(2980306, 418417, 67553, '<td valign="top">Beautiful dog.</td>', 'Beautiful dog.', '2006-10-31 22:23:15.000000', NULL, 1),
(2980310, 415901, 30982, '<td valign="top">Nice simple composition and I like the pattern to the birds - they look like they''re in a circling/holding position.  There''s a halo around them that may be due to sharpening or contrast, perhaps.</td>', 'Nice simple composition and I like the pattern to the birds - they look like they''re in a circling/holding position.  There''s a halo around them that may be due to sharpening or contrast, perhaps.', '2006-10-31 22:24:07.000000', NULL, 1),
