(2981100, 419299, 61119, '<td valign="top">This was my favorite of all of the wind shots.  Thank you for sharing.</td>', 'This was my favorite of all of the wind shots.  Thank you for sharing.', '2006-11-01 01:00:47.000000', NULL, 1),
