(2986524, 418375, 64009, '<td valign="top">u make me laugh..i will give you a 7 !!</td>', 'u make me laugh..i will give you a 7 !!', '2006-11-01 20:32:50.000000', NULL, 1),
(2986528, 417041, 64009, '<td valign="top">cool though overprocessed my friend...looks like more a cartoon than a picture !!</td>', 'cool though overprocessed my friend...looks like more a cartoon than a picture !!', '2006-11-01 20:34:15.000000', NULL, 1),
(2986546, 417819, 64009, '<td valign="top">very nice composition with the frame !! neat.</td>', 'very nice composition with the frame !! neat.', '2006-11-01 20:39:02.000000', NULL, 1),
(2986646, 418152, 45790, '<td valign="top">Seems mostly out of focus.</td>', 'Seems mostly out of focus.', '2006-11-01 21:03:37.000000', NULL, 1),
(2986659, 419121, 45790, '<td valign="top">I would have gotten in tighter to get the fence and sky out of the frame -- they aren''t beige and the fence is particularly annoying.</td>', 'I would have gotten in tighter to get the fence and sky out of the frame -- they aren''t beige and the fence is particularly annoying.', '2006-11-01 21:05:50.000000', NULL, 1),
(2986675, 418623, 45790, '<td valign="top">Beautiful colors, great reflection on sand.</td>', 'Beautiful colors, great reflection on sand.', '2006-11-01 21:08:59.000000', NULL, 1),
(2986685, 418183, 45790, '<td valign="top">I like the storm. I hope others do, too, and aren''t put off by the natural colors.</td>', 'I like the storm. I hope others do, too, and aren''t put off by the natural colors.', '2006-11-01 21:10:05.000000', NULL, 1),
(2986703, 418435, 45790, '<td valign="top">I''d prefer this without the glare (not only on the left, but also in the grass on the right). Lens hood?</td>', 'I''d prefer this without the glare (not only on the left, but also in the grass on the right). Lens hood?', '2006-11-01 21:14:29.000000', NULL, 1),
(2986706, 419332, 63218, '<td valign="top">your flag is displayed backwards, the stars should be in the L corner</td>', 'your flag is displayed backwards, the stars should be in the L corner', '2006-11-01 21:15:28.000000', NULL, 1),
(2986707, 418815, 45790, '<td valign="top">Nice, fun shot!</td>', 'Nice, fun shot!', '2006-11-01 21:15:48.000000', NULL, 1),
(2986708, 419299, 63218, '<td valign="top">the buildings look so temporary</td>', 'the buildings look so temporary', '2006-11-01 21:16:13.000000', NULL, 1),
(2986716, 419329, 63218, '<td valign="top">I wish you''d flipped this, the flag is displayed backwards, the stars should be in the L corner :(</td>', 'I wish you''d flipped this, the flag is displayed backwards, the stars should be in the L corner :(', '2006-11-01 21:18:25.000000', NULL, 1),
(2986717, 419178, 67541, '<td valign="top">Great colors, fantastic idea.</td>', 'Great colors, fantastic idea.', '2006-11-01 21:18:30.000000', NULL, 1),
(2986719, 419204, 45790, '<td valign="top">Well done, colorful waterfall.</td>', 'Well done, colorful waterfall.', '2006-11-01 21:18:47.000000', NULL, 1),
(2986936, 418623, 64571, '<td valign="top">Absolutely fantastic - definately my favorite!  Beautiful work!!!</td>', 'Absolutely fantastic - definately my favorite!  Beautiful work!!!', '2006-11-01 22:03:56.000000', NULL, 1),
(2986949, 419141, 64571, '<td valign="top">Spectacular!  One of my favorites in this challenge.  Beautiful!</td>', 'Spectacular!  One of my favorites in this challenge.  Beautiful!', '2006-11-01 22:06:01.000000', NULL, 1),
(2986953, 419299, 64571, '<td valign="top">Wow - this is awesome!  Certainly in my top 3!!!  Great capture!</td>', 'Wow - this is awesome!  Certainly in my top 3!!!  Great capture!', '2006-11-01 22:07:11.000000', NULL, 1),
(2986957, 416120, 64571, '<td valign="top">Beautiful photo</td>', 'Beautiful photo', '2006-11-01 22:07:52.000000', NULL, 1),
(2986964, 419362, 64571, '<td valign="top">great shot</td>', 'great shot', '2006-11-01 22:08:38.000000', NULL, 1),
(2986968, 418521, 64571, '<td valign="top">Simply awesome!</td>', 'Simply awesome!', '2006-11-01 22:09:32.000000', NULL, 1),
(2986981, 419303, 64571, '<td valign="top">unbelivable capture</td>', 'unbelivable capture', '2006-11-01 22:11:32.000000', NULL, 1),
(2986992, 419019, 64571, '<td valign="top">cute - great title</td>', 'cute - great title', '2006-11-01 22:13:47.000000', NULL, 1),
(2987375, 419249, 12253, '<td valign="top">Superb tones, and I love the inclusion of the animal.  I do notice the blown sky, but really, here, I don''t mind it, as it serves to emphasize the trees.  Great BW conversion.  10 from me!</td>', 'Superb tones, and I love the inclusion of the animal.  I do notice the blown sky, but really, here, I don''t mind it, as it serves to emphasize the trees.  Great BW conversion.  10 from me!', '2006-11-01 23:42:00.000000', NULL, 1),
(2987431, 418842, 38706, '<td valign="top">Great job on the lighting - Her left sholder is a little bright but it still a great image.</td>', 'Great job on the lighting - Her left sholder is a little bright but it still a great image.', '2006-11-01 23:56:03.000000', NULL, 1),
(2987550, 419194, 67248, '<td valign="top">this has a very nice "motion effect" to this photo.</td>', 'this has a very nice "motion effect" to this photo.', '2006-11-02 00:27:05.000000', NULL, 1),
(2987672, 418842, 18339, '<td valign="top">Beautiful work ;)</td>', 'Beautiful work ;)', '2006-11-02 01:33:44.000000', NULL, 1),
(2987675, 417415, 18339, '<td valign="top">Love the smile :)</td>', 'Love the smile :)', '2006-11-02 01:34:26.000000', NULL, 1),
(2987679, 419141, 18339, '<td valign="top">Nice work, the hair not blowing adds an interesting touch.</td>', 'Nice work, the hair not blowing adds an interesting touch.', '2006-11-02 01:35:38.000000', NULL, 1),
(2987795, 418453, 67324, '<td valign="top">I wanted to do a shot just like this. Like Jeremy? on top gear driving the Ariel Atom.</td>', 'I wanted to do a shot just like this. Like Jeremy? on top gear driving the Ariel Atom.', '2006-11-02 03:05:36.000000', NULL, 1),
(2988313, 418679, 64035, '<td valign="top">This is a great picture - the figure is really well photographed. I''m curiously irritated by the bottom left hand corner - for some reason it really intrudes into the shot, pulling my eyes away from the subject in a quite unpleasant way. Other than that, it''s a lovely picture.</td>', 'This is a great picture - the figure is really well photographed. I''m curiously irritated by the bottom left hand corner - for some reason it really intrudes into the shot, pulling my eyes away from the subject in a quite unpleasant way. Other than that, it''s a lovely picture.', '2006-11-02 08:16:24.000000', NULL, 1),
(2988318, 417041, 64035, '<td valign="top">This is a great idea, and all the elements should work, but to me the net result feels staged and fake. One problem is that the model''s hair and dress don''t match the wind force implied by the stance and the umbrella. Also, the tones of the whole image are almost cartoony - and her right arm in particular looks oversharpened. Still, it''s an ambitious and creditable effort.</td>', 'This is a great idea, and all the elements should work, but to me the net result feels staged and fake. One problem is that the model''s hair and dress don''t match the wind force implied by the stance and the umbrella. Also, the tones of the whole image are almost cartoony - and her right arm in particular looks oversharpened. Still, it''s an ambitious and creditable effort.', '2006-11-02 08:18:15.000000', NULL, 1),
(2988322, 418823, 27524, '<td valign="top">I like the contrast of grey and color.</td>', 'I like the contrast of grey and color.', '2006-11-02 08:19:25.000000', NULL, 1),
(2988324, 418341, 64035, '<td valign="top">Nice shot, with good contrast and great background seperation. I think there could either be more or less space on the right hand side - it feels proportionally wrong in some way. I''m not convinced about the border, either. Love the sharpness of the foreground, and the expression and the line of his arm is fabulous.</td>', 'Nice shot, with good contrast and great background seperation. I think there could either be more or less space on the right hand side - it feels proportionally wrong in some way. I''m not convinced about the border, either. Love the sharpness of the foreground, and the expression and the line of his arm is fabulous.', '2006-11-02 08:19:59.000000', NULL, 1),
(2988327, 418990, 30049, '<td valign="top">Nice portrait shot of a pretty young lady.  To look at this photo outside the scope of this challenge theme the viewer would be hard pressed to say the subject is ''Wind'' IMO.  Even knowing the theme it''s hard to know if anything is moving or blowing in the ''breeze'' (your title).  If it''s her hair, then it''s lost in the dark background, if it''s the scarf, it looks to be hanging fairly naturally.  Not trying to be rude or anything, just stating what hit me as a first impression of this photograph and it''s relation to the challenge.  Best of luck to you.</td>', 'Nice portrait shot of a pretty young lady.  To look at this photo outside the scope of this challenge theme the viewer would be hard pressed to say the subject is ''Wind'' IMO.  Even knowing the theme it''s hard to know if anything is moving or blowing in the ''breeze'' (your title).  If it''s her hair, then it''s lost in the dark background, if it''s the scarf, it looks to be hanging fairly naturally.  Not trying to be rude or anything, just stating what hit me as a first impression of this photograph and it''s relation to the challenge.  Best of luck to you.', '2006-11-02 08:21:45.000000', NULL, 1),
(2988329, 418521, 27524, '<td valign="top">Nice and impresive...lovely golden sparks in the water.</td>', 'Nice and impresive...lovely golden sparks in the water.', '2006-11-02 08:21:47.000000', NULL, 1),
(2988330, 418689, 27524, '<td valign="top">Simple and nice b&amp;w.</td>', 'Simple and nice b&w.', '2006-11-02 08:22:06.000000', NULL, 1),
(2988340, 419194, 30049, '<td valign="top">I never have tried one of these match setup shots.  Looks like fun - think I''ll give it a go sometime soon.  :)  In your case, I like how you''ve indicated some air movement with the flame flowing to the right.  Nice job of exposing correctly to get the flame and smoke showing properly.  Good luck in the challenge.</td>', 'I never have tried one of these match setup shots.  Looks like fun - think I''ll give it a go sometime soon.  :)  In your case, I like how you''ve indicated some air movement with the flame flowing to the right.  Nice job of exposing correctly to get the flame and smoke showing properly.  Good luck in the challenge.', '2006-11-02 08:24:44.000000', NULL, 1),
(2988352, 416120, 64035, '<td valign="top">Lovely sky, and I think I get the oblique approach to the challenge. Good silhouettes on the boats, too.</td>', 'Lovely sky, and I think I get the oblique approach to the challenge. Good silhouettes on the boats, too.', '2006-11-02 08:29:08.000000', NULL, 1),
(2988356, 419141, 30049, '<td valign="top">Thought I saw another image similar - must be something about wind, waves, and black flowing garments.  :D  You picked a nice broody day to take this shot.  The background clouds add a nice element.  For me the waves are the main indicator of ''Wind''.  The fringe of her black outfit appears to be in motion from her movement.  Wait!  I just noticed (seriously) that that is not her arm off to the side.  At first glance I really thought the light colored underside of the garment was her arm reaching out.  An interesting optical illusion.  Unfortunately, one that may fool others as well that don''t take a long enough look.  Regardless, you should still do quite well with the other key items that make up this composition.  Best of luck to you in the challenge.</td>', 'Thought I saw another image similar - must be something about wind, waves, and black flowing garments.  :D  You picked a nice broody day to take this shot.  The background clouds add a nice element.  For me the waves are the main indicator of ''Wind''.  The fringe of her black outfit appears to be in motion from her movement.  Wait!  I just noticed (seriously) that that is not her arm off to the side.  At first glance I really thought the light colored underside of the garment was her arm reaching out.  An interesting optical illusion.  Unfortunately, one that may fool others as well that don''t take a long enough look.  Regardless, you should still do quite well with the other key items that make up this composition.  Best of luck to you in the challenge.', '2006-11-02 08:29:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2988359, 417899, 64035, '<td valign="top">Great sea, and an interesting approach to this. I could do without the scrubby bit of water at the bottom, though.</td>', 'Great sea, and an interesting approach to this. I could do without the scrubby bit of water at the bottom, though.', '2006-11-02 08:30:36.000000', NULL, 1),
(2988361, 419395, 27524, '<td valign="top">Nice done...very interesting landscape.</td>', 'Nice done...very interesting landscape.', '2006-11-02 08:30:46.000000', NULL, 1),
(2988367, 418571, 64035, '<td valign="top">Great idea. Some other people have fallen into the same trap though - his clothes aren''t blown in the same way as the umbrella and pose suggest, and as a result the image - to me - reads as fake. It also looks a bit over-sharpened around his jeans - almost like it''s a cut and paste effort. I like the blue against the dark red though, very much.</td>', 'Great idea. Some other people have fallen into the same trap though - his clothes aren''t blown in the same way as the umbrella and pose suggest, and as a result the image - to me - reads as fake. It also looks a bit over-sharpened around his jeans - almost like it''s a cut and paste effort. I like the blue against the dark red though, very much.', '2006-11-02 08:32:36.000000', NULL, 1),
(2988370, 419382, 30049, '<td valign="top">Wow.  That IS some wicked hair.  :D  The first thing I notice is the strange color of the background.  To me it appears to be red/maroon?  Why?  As for the hair and the girl.  The hair is certainly interesting and is the main connection to the challenge theme for me.  I would like to see more of her face but it''s a little underexposed.  A small amount of fill flash may have helped here.  All JMO of course.  Good luck in the challenge.</td>', 'Wow.  That IS some wicked hair.  :D  The first thing I notice is the strange color of the background.  To me it appears to be red/maroon?  Why?  As for the hair and the girl.  The hair is certainly interesting and is the main connection to the challenge theme for me.  I would like to see more of her face but it''s a little underexposed.  A small amount of fill flash may have helped here.  All JMO of course.  Good luck in the challenge.', '2006-11-02 08:32:55.000000', NULL, 1),
(2988373, 417768, 27524, '<td valign="top">Very interesting looks like seaweed in water.</td>', 'Very interesting looks like seaweed in water.', '2006-11-02 08:34:38.000000', NULL, 1),
(2988377, 419299, 27524, '<td valign="top">Bautiful...nice harmonic colors and motion.</td>', 'Bautiful...nice harmonic colors and motion.', '2006-11-02 08:35:38.000000', NULL, 1),
(2988380, 418793, 30049, '<td valign="top">That tree has seen it''s fair share of winds it appears.  :D  By picking a rainy day you''ve done a nice job of creating the illusion that the tree is actually blowing over.  Clever.  This photo seems a little flat to me, like it could use some tweaking with levels and a touch more contrast.  Could be just the overcast conditions or the color tones...  Anyway, good luck in the challenge.</td>', 'That tree has seen it''s fair share of winds it appears.  :D  By picking a rainy day you''ve done a nice job of creating the illusion that the tree is actually blowing over.  Clever.  This photo seems a little flat to me, like it could use some tweaking with levels and a touch more contrast.  Could be just the overcast conditions or the color tones...  Anyway, good luck in the challenge.', '2006-11-02 08:36:06.000000', NULL, 1),
(2988424, 418375, 30049, '<td valign="top">Seems a bit contrived to me.  Sorry.</td>', 'Seems a bit contrived to me.  Sorry.', '2006-11-02 08:50:10.000000', NULL, 1),
(2988431, 418914, 30049, '<td valign="top">Spent some time on that selective desat I''ll bet.  :)  Interesting approach to the challenge.  The branch certainly stands out this way.  The lighting is somewhat harsh and you''ve lost detail in a couple of places.  May have also pushed the saturation just a little too much.  Not really seeing a whole lot of ''Wind'' here.  If there is motion indicating some wind it''s not evident in a strong enough manner IMO.  All JMO of course.  Good luck in the challenge.</td>', 'Spent some time on that selective desat I''ll bet.  :)  Interesting approach to the challenge.  The branch certainly stands out this way.  The lighting is somewhat harsh and you''ve lost detail in a couple of places.  May have also pushed the saturation just a little too much.  Not really seeing a whole lot of ''Wind'' here.  If there is motion indicating some wind it''s not evident in a strong enough manner IMO.  All JMO of course.  Good luck in the challenge.', '2006-11-02 08:53:23.000000', NULL, 1),
(2988438, 419298, 30049, '<td valign="top">The impression of a windy day is quite evident in your photo.  Well done in that regard.  The combination of seagulls in the wind and the waves coming in make a strong connection to the challenge.  Technically, you''re a bit blown out in the highlights, some flare is making the shoreline hazy in the distance (UV/Polarizer may have helped some along with a lens hood, even a hat).  The biggest thing that is going to zap you on this is the slanted horizon.  That just drives many photographers on this site crazy!  :D  Unfortunately it''s slanted enough that it''s evident to even the casual viewer.  All of the above is JMO of course.  Wish you luck in the challenge.</td>', 'The impression of a windy day is quite evident in your photo.  Well done in that regard.  The combination of seagulls in the wind and the waves coming in make a strong connection to the challenge.  Technically, you''re a bit blown out in the highlights, some flare is making the shoreline hazy in the distance (UV/Polarizer may have helped some along with a lens hood, even a hat).  The biggest thing that is going to zap you on this is the slanted horizon.  That just drives many photographers on this site crazy!  :D  Unfortunately it''s slanted enough that it''s evident to even the casual viewer.  All of the above is JMO of course.  Wish you luck in the challenge.', '2006-11-02 08:57:37.000000', NULL, 1),
(2988456, 418969, 30049, '<td valign="top">Hmmm.  I like it for it''s simplicity, and I also like the fact that you''re presenting the image without a long winded (pun intended) title.  :D  I''m undecided whether I like the large expanse of sky or not.  It''s a bit mundane (even a small cloud or two would help - not that you can control THAT, he-he).  I kind of get the impression you really wanted to include that third seagull on the left, therefore the larger sky canvas.  Not sure that you''re maximizing the ''Wind'' story by doing this.  Some that enjoy a minimalistic approach will enjoy this composition probably a little more I guess.  Sorry for rambling, especially since I''ve not formulated any strong opinion on your photograph.  Best of luck to you in the challenge.</td>', 'Hmmm.  I like it for it''s simplicity, and I also like the fact that you''re presenting the image without a long winded (pun intended) title.  :D  I''m undecided whether I like the large expanse of sky or not.  It''s a bit mundane (even a small cloud or two would help - not that you can control THAT, he-he).  I kind of get the impression you really wanted to include that third seagull on the left, therefore the larger sky canvas.  Not sure that you''re maximizing the ''Wind'' story by doing this.  Some that enjoy a minimalistic approach will enjoy this composition probably a little more I guess.  Sorry for rambling, especially since I''ve not formulated any strong opinion on your photograph.  Best of luck to you in the challenge.', '2006-11-02 09:03:47.000000', NULL, 1),
(2988465, 419206, 30049, '<td valign="top">The first thing I thought of, because of your title, is a leaf blower.  :D  Am I right?  I had considered using one as well.  He-he.  The photo is "ok".  I think it needs something more for scope and context.  A tree or a building, etc...  The lighting is also funny.  There''s a big shady spot in the lower right - were you blocking the sun while holding the camera or something?  Some of the lighter colored leaves are overexposed.  If you were really sold on this image you could have spent a little time using some editing tools like a burn brush or layer to tone the hotspots down a little.  Just some observations.  Good luck in the challenge.</td>', 'The first thing I thought of, because of your title, is a leaf blower.  :D  Am I right?  I had considered using one as well.  He-he.  The photo is "ok".  I think it needs something more for scope and context.  A tree or a building, etc...  The lighting is also funny.  There''s a big shady spot in the lower right - were you blocking the sun while holding the camera or something?  Some of the lighter colored leaves are overexposed.  If you were really sold on this image you could have spent a little time using some editing tools like a burn brush or layer to tone the hotspots down a little.  Just some observations.  Good luck in the challenge.', '2006-11-02 09:08:28.000000', NULL, 1),
(2988471, 417692, 30049, '<td valign="top">Nice placement of the seagull coming into the frame.  The wings form a nice diagonal.  Some interest in the background with the geese but not overbearing because of the bg blur.  Biggest hit you''re going to take is for losing detail in the tail with the blownout whites.  Good luck in the challenge.</td>', 'Nice placement of the seagull coming into the frame.  The wings form a nice diagonal.  Some interest in the background with the geese but not overbearing because of the bg blur.  Biggest hit you''re going to take is for losing detail in the tail with the blownout whites.  Good luck in the challenge.', '2006-11-02 09:11:14.000000', NULL, 1),
(2988477, 419114, 30049, '<td valign="top">Ok.  You made me count them.  :D  Good time of day you selected to capture this image.  Nice warm sun light and a tint of color in the sky.  The building is a little distracting but probably unavoidable, especially if you wanted to include the lightpost (which I think was a good choice overall).  Best of luck to you in the challenge.</td>', 'Ok.  You made me count them.  :D  Good time of day you selected to capture this image.  Nice warm sun light and a tint of color in the sky.  The building is a little distracting but probably unavoidable, especially if you wanted to include the lightpost (which I think was a good choice overall).  Best of luck to you in the challenge.', '2006-11-02 09:13:33.000000', NULL, 1),
(2988484, 419202, 30049, '<td valign="top">It''s "ok".  Interesting POV.  The cross bar is distracting but at least you used it too advantage to form a diagonal line of interest in your composition.  Good luck in the challenge.</td>', 'It''s "ok".  Interesting POV.  The cross bar is distracting but at least you used it too advantage to form a diagonal line of interest in your composition.  Good luck in the challenge.', '2006-11-02 09:14:41.000000', NULL, 1),
(2988494, 419017, 30049, '<td valign="top">Hmmm.  Clever.  Perhaps too clever and subtle for quick viewing voters?  I usually like sepia and B/W conversions, but I wonder in this case why you went down that path?  That leaf would have stood out well against a blue sky.  Maybe the color of her clothing was too distracting?  Sorry for all the questions.  :D  I like the positioning of the subjects in this.  Good luck.</td>', 'Hmmm.  Clever.  Perhaps too clever and subtle for quick viewing voters?  I usually like sepia and B/W conversions, but I wonder in this case why you went down that path?  That leaf would have stood out well against a blue sky.  Maybe the color of her clothing was too distracting?  Sorry for all the questions.  :D  I like the positioning of the subjects in this.  Good luck.', '2006-11-02 09:18:01.000000', NULL, 1),
(2988498, 419361, 30049, '<td valign="top">Cute.  Maybe if the lighting was setup a little different I would enjoy this more.  The front tire feels out of place and harshly lit.  Good luck.</td>', 'Cute.  Maybe if the lighting was setup a little different I would enjoy this more.  The front tire feels out of place and harshly lit.  Good luck.', '2006-11-02 09:19:15.000000', NULL, 1),
(2988561, 418183, 30049, '<td valign="top">First thought that comes to mind is power.  You''ve done a nice job of exposing on this as the foreground rocks show nice detail and the whites are in control (maybe a tad shy of true white).  A minor boost in contrast might help this shot a little, but it could be this cruddy work monitor. :D  A little tweak in levels or histogram adjustment to bring the whites up a bit is a consideration.  Anyway, nice photo overall.  Good luck in the challenge.</td>', 'First thought that comes to mind is power.  You''ve done a nice job of exposing on this as the foreground rocks show nice detail and the whites are in control (maybe a tad shy of true white).  A minor boost in contrast might help this shot a little, but it could be this cruddy work monitor. :D  A little tweak in levels or histogram adjustment to bring the whites up a bit is a consideration.  Anyway, nice photo overall.  Good luck in the challenge.', '2006-11-02 09:44:51.000000', NULL, 1),
(2988644, 418577, 30049, '<td valign="top">Nice colors and tones.  Good connection to the challenge theme by strong visual illustration of wind in action.  On the down side, the horizon is substantially slanted to the left.  I''m surprised there''s any water left in the lake!  Well, just busting your chops a little with that last comment.  :D  Good luck in the challenge.</td>', 'Nice colors and tones.  Good connection to the challenge theme by strong visual illustration of wind in action.  On the down side, the horizon is substantially slanted to the left.  I''m surprised there''s any water left in the lake!  Well, just busting your chops a little with that last comment.  :D  Good luck in the challenge.', '2006-11-02 10:09:24.000000', NULL, 1),
(2988648, 419365, 30049, '<td valign="top">Nice B/W image with strong contrast.  Looks good even on this cruddy work monitor.  :D  Interesting to look at and shows a connection to the challenge theme.  Well done.  Good luck in the challenge.</td>', 'Nice B/W image with strong contrast.  Looks good even on this cruddy work monitor.  :D  Interesting to look at and shows a connection to the challenge theme.  Well done.  Good luck in the challenge.', '2006-11-02 10:10:40.000000', NULL, 1),
(2988664, 419096, 30049, '<td valign="top">Cool costume!  :D  I like the way the cape comes across the photo at an angle to keep the viewer inside the natural framing of this shot.  Nice vivid color.  The only thing on the down side for me is the whole setup seems, well, setup.  :)  Good luck in the challenge.</td>', 'Cool costume!  :D  I like the way the cape comes across the photo at an angle to keep the viewer inside the natural framing of this shot.  Nice vivid color.  The only thing on the down side for me is the whole setup seems, well, setup.  :)  Good luck in the challenge.', '2006-11-02 10:13:44.000000', NULL, 1),
(2988744, 419387, 30049, '<td valign="top">Looks like Lake Michigan.  You''ve certainly captured wind at work in this photo.  The color tone selection works well to give it a harsh gritty feeling.  Nicely done!  Hope your gear was ok in that environment!  Good luck in the challenge.</td>', 'Looks like Lake Michigan.  You''ve certainly captured wind at work in this photo.  The color tone selection works well to give it a harsh gritty feeling.  Nicely done!  Hope your gear was ok in that environment!  Good luck in the challenge.', '2006-11-02 10:31:13.000000', NULL, 1),
(2988747, 418341, 36619, '<td valign="top">there doesn''t seem to be any actual wind here as far as i can tell. which makes his pose to me that much more impressive, he certainly makes one believe that there is an invisible force that he''s fighting against. i also am glad for the b&amp;w and the blurred background which helps keep the focus on the man. 9</td>', 'there doesn''t seem to be any actual wind here as far as i can tell. which makes his pose to me that much more impressive, he certainly makes one believe that there is an invisible force that he''s fighting against. i also am glad for the b&w and the blurred background which helps keep the focus on the man. 9', '2006-11-02 10:32:08.000000', NULL, 1),
(2988757, 418513, 36619, '<td valign="top">very colorful and interesting location. a different crop or angle probably would serve it better, but i think it''s still well done.</td>', 'very colorful and interesting location. a different crop or angle probably would serve it better, but i think it''s still well done.', '2006-11-02 10:34:43.000000', NULL, 1),
