(2988864, 417172, 62187, '<td valign="top">I think I''m picking your for the blue. 10</td>', 'I think I''m picking your for the blue. 10', '2006-11-02 11:17:05.000000', NULL, 1),
(2988867, 417900, 62187, '<td valign="top">It''s actually not a very good photo. However, I feel it meets the challenge better then most photos. I wish it would do better then the ones that pretend to show the effects of wind. I''m sorry, but birds flying is not ''Wind'' - your photo is.</td>', 'It''s actually not a very good photo. However, I feel it meets the challenge better then most photos. I wish it would do better then the ones that pretend to show the effects of wind. I''m sorry, but birds flying is not ''Wind'' - your photo is.', '2006-11-02 11:19:35.000000', NULL, 1),
(2988868, 419107, 62187, '<td valign="top">I think you have the best shot of the challenge. I don''t care for most so I haven''t decided if I''m voting or not..if I do, you''ll certainly get a 10. I came back to vote...10</td>', 'I think you have the best shot of the challenge. I don''t care for most so I haven''t decided if I''m voting or not..if I do, you''ll certainly get a 10. I came back to vote...10', '2006-11-02 11:20:17.000000', NULL, 1),
