(2988933, 417415, 24715, '<td valign="top">Made me smile. Very happy photo. :-)</td>', 'Made me smile. Very happy photo. :-)', '2006-11-02 11:40:25.000000', NULL, 1),
(2988943, 419141, 24715, '<td valign="top">Nice photo. I like the dimness and the colors. I think I would have liked more space in front of her.</td>', 'Nice photo. I like the dimness and the colors. I think I would have liked more space in front of her.', '2006-11-02 11:43:19.000000', NULL, 1),
