INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2996515, 419387, 49963, '<td valign="top">Just beautiful.</td>', 'Just beautiful.', '2006-11-03 23:38:04.000000', NULL, 1),
(2996606, 417041, 36988, '<td valign="top">An excellent composition. She''s not giving way at all and the processing is unique enough that it adds to a great image and in fact enhances the style and mood. Of course it''s posed but so what. Ah what the hell coming back for the extra mark for coolness... :)</td>', 'An excellent composition. She''s not giving way at all and the processing is unique enough that it adds to a great image and in fact enhances the style and mood. Of course it''s posed but so what. Ah what the hell coming back for the extra mark for coolness... :)', '2006-11-04 00:11:52.000000', NULL, 1),
(2996607, 419299, 36988, '<td valign="top">What a beautifully surreal image. Looks very futuristic to me and I think this works on many levels. Good luck!</td>', 'What a beautifully surreal image. Looks very futuristic to me and I think this works on many levels. Good luck!', '2006-11-04 00:11:57.000000', NULL, 1),
(2996608, 418752, 36988, '<td valign="top">An excellent image. Not sure what the background is... common sense says it can''t be clouds, but I sure am willing to believe they are. Great job!</td>', 'An excellent image. Not sure what the background is... common sense says it can''t be clouds, but I sure am willing to believe they are. Great job!', '2006-11-04 00:12:14.000000', NULL, 1),
(2996609, 418184, 36988, '<td valign="top">This image is almost perfect. It tells me everything about the day and the subject is so interesting. Great job!</td>', 'This image is almost perfect. It tells me everything about the day and the subject is so interesting. Great job!', '2006-11-04 00:12:19.000000', NULL, 1),
(2996611, 418842, 36988, '<td valign="top">Beauty and style to the max. A very classy entry and one of my favs. Nicely done! Nope... gotta give the 10.</td>', 'Beauty and style to the max. A very classy entry and one of my favs. Nicely done! Nope... gotta give the 10.', '2006-11-04 00:12:52.000000', NULL, 1),
(2996613, 417899, 36988, '<td valign="top">A definate standout in the challenge and very likely a ribbon contender. Excellent job!</td>', 'A definate standout in the challenge and very likely a ribbon contender. Excellent job!', '2006-11-04 00:13:03.000000', NULL, 1),
(2996614, 419121, 36988, '<td valign="top">Beutifully done. A technical delight to see. It dosn''t scream wind to me and it''s a bit subtle for the challenge but high marks regardless. Well done!</td>', 'Beutifully done. A technical delight to see. It dosn''t scream wind to me and it''s a bit subtle for the challenge but high marks regardless. Well done!', '2006-11-04 00:13:10.000000', NULL, 1),
(2996615, 418498, 36988, '<td valign="top">An excellent image. Might have liked to see him stand out a bit more from the background... just a bit dull to the right but nonetheless outstanding.</td>', 'An excellent image. Might have liked to see him stand out a bit more from the background... just a bit dull to the right but nonetheless outstanding.', '2006-11-04 00:13:33.000000', NULL, 1),
(2996616, 419365, 36988, '<td valign="top">I like this alot. A very natural capture with tons of personality and... wait for it... a bit of wind subtly present. Nice job! 8</td>', 'I like this alot. A very natural capture with tons of personality and... wait for it... a bit of wind subtly present. Nice job! 8', '2006-11-04 00:13:52.000000', NULL, 1),
(2996621, 417381, 36988, '<td valign="top">The processing here is incredibly good but unfortunately I see little in the way of wind no matter how hard I look. In fact it strikes me as a very calm and peaceful place to visit. Nonetheless, I''ll give this higher than normal marks for talent and obvious visual excellence and trust there is a tie in to the challenge that I quite don''t see other than a tittle tie in.</td>', 'The processing here is incredibly good but unfortunately I see little in the way of wind no matter how hard I look. In fact it strikes me as a very calm and peaceful place to visit. Nonetheless, I''ll give this higher than normal marks for talent and obvious visual excellence and trust there is a tie in to the challenge that I quite don''t see other than a tittle tie in.', '2006-11-04 00:15:11.000000', NULL, 1),
(2996624, 417415, 36988, '<td valign="top">A perfect literal take on the challenge. A little too light in areas of the sky and sense that it should be rotated to the left a touch but nonetheless certainly worthy of high marks. Good job!</td>', 'A perfect literal take on the challenge. A little too light in areas of the sky and sense that it should be rotated to the left a touch but nonetheless certainly worthy of high marks. Good job!', '2006-11-04 00:15:33.000000', NULL, 1),
(2996631, 418966, 36988, '<td valign="top">This image leaves me feeling visually confused... and that in this case is a good thing. seems there''s alot of contradictions here but to me they work beautifully togethjer. Hope you get very high marks for this overall because I do see this as one of the standout entries.</td>', 'This image leaves me feeling visually confused... and that in this case is a good thing. seems there''s alot of contradictions here but to me they work beautifully togethjer. Hope you get very high marks for this overall because I do see this as one of the standout entries.', '2006-11-04 00:16:51.000000', NULL, 1),
(2996632, 418890, 36988, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2006-11-04 00:17:13.000000', NULL, 1),
(2996649, 418689, 36988, '<td valign="top">Beautiful. Great tonal range and perfect processing. Nice job!</td>', 'Beautiful. Great tonal range and perfect processing. Nice job!', '2006-11-04 00:22:12.000000', NULL, 1),
(2996679, 419339, 36988, '<td valign="top">At first glance, I wasn''t sure, but now I am... I really like this alot. Just a natural, literal take on the challenge with lots of personality. Great job! bumping up.</td>', 'At first glance, I wasn''t sure, but now I am... I really like this alot. Just a natural, literal take on the challenge with lots of personality. Great job! bumping up.', '2006-11-04 00:31:14.000000', NULL, 1),
(2996687, 416167, 36988, '<td valign="top">Great expression and very nicely done. Final bump... :)</td>', 'Great expression and very nicely done. Final bump... :)', '2006-11-04 00:34:08.000000', NULL, 1),
(2996690, 418341, 36988, '<td valign="top">A very stylish entry and beautifully pulled off. Great job 8</td>', 'A very stylish entry and beautifully pulled off. Great job 8', '2006-11-04 00:34:45.000000', NULL, 1),
(2996694, 418815, 36988, '<td valign="top">The only thing keeping this image from good to great is 1 leaf and unfortunatley there''s not alot you can do. I''m left really wishing I could see her face and smile. 7 <br/>Ah nuts... it''s great enough. Bumping to 8.</td>', 'The only thing keeping this image from good to great is 1 leaf and unfortunatley there''s not alot you can do. I''m left really wishing I could see her face and smile. 7 Ah nuts... it''s great enough. Bumping to 8.', '2006-11-04 00:36:15.000000', NULL, 1),
(2996718, 418752, 29274, '<td valign="top">Love the facial Expression, great colors.</td>', 'Love the facial Expression, great colors.', '2006-11-04 00:44:52.000000', NULL, 1),
(2996720, 418499, 50695, '<td valign="top">Boys and Kites<br/> <br/>The world looks folded in three,<br/>sky on water on white sand.<br/>In the crease run little boys<br/>away from their laughing kites,<br/>the brilliant colors stretched<br/>on a geometric frame.<br/> <br/>Capable of flight, prone<br/>to crashes, they are<br/>hard on themselves, rigid, yet<br/>they fall so bravely,<br/>headlong into shore.<br/> <br/>A boy running with a frail string<br/>gripped in both hands<br/>knows unhappiness,<br/>feels it bouncing just behind.</td>', 'Boys and Kites The world looks folded in three,sky on water on white sand.In the crease run little boysaway from their laughing kites,the brilliant colors stretchedon a geometric frame. Capable of flight, proneto crashes, they arehard on themselves, rigid, yetthey fall so bravely,headlong into shore. A boy running with a frail stringgripped in both handsknows unhappiness,feels it bouncing just behind.', '2006-11-04 00:44:58.000000', NULL, 1),
(2996781, 419087, 44490, '<td valign="top">Nice idea if you could really emphasize the wind effects.  Eyes and brighter levels would help.</td>', 'Nice idea if you could really emphasize the wind effects.  Eyes and brighter levels would help.', '2006-11-04 01:12:12.000000', NULL, 1),
(2996782, 416199, 44490, '<td valign="top">Nice idea, but the image needs something stable and sharp as a focus to keep us from getting lost in the motion blur.</td>', 'Nice idea, but the image needs something stable and sharp as a focus to keep us from getting lost in the motion blur.', '2006-11-04 01:12:16.000000', NULL, 1),
(2996787, 419124, 44490, '<td valign="top">Nice pose and flowing scarves, but image looks over-exposed.  Rescue with level adjustment and increased saturation.</td>', 'Nice pose and flowing scarves, but image looks over-exposed.  Rescue with level adjustment and increased saturation.', '2006-11-04 01:15:53.000000', NULL, 1),
(2996792, 419217, 44490, '<td valign="top">Nice idea.  Focus on near thumb with DOF to include far thumb would be better.</td>', 'Nice idea.  Focus on near thumb with DOF to include far thumb would be better.', '2006-11-04 01:17:01.000000', NULL, 1),
(2996796, 419206, 44490, '<td valign="top">Nice blend of motion blur and sharp leaves.  Image is too busy for most tastes, and needs an subject to draw our focus.</td>', 'Nice blend of motion blur and sharp leaves.  Image is too busy for most tastes, and needs an subject to draw our focus.', '2006-11-04 01:18:29.000000', NULL, 1),
(2996801, 418347, 44490, '<td valign="top">Nice sharp focus on foreground, but the background is distracting and confusing, consider shallower DOF for more separation.</td>', 'Nice sharp focus on foreground, but the background is distracting and confusing, consider shallower DOF for more separation.', '2006-11-04 01:20:27.000000', NULL, 1),
(2996805, 419323, 44490, '<td valign="top">Nice composition, colors, and bokeh.  Wish for clearer detail on leaf.  Glad to see simple and effective capture of motion.</td>', 'Nice composition, colors, and bokeh.  Wish for clearer detail on leaf.  Glad to see simple and effective capture of motion.', '2006-11-04 01:22:39.000000', NULL, 1),
(2996807, 419296, 44490, '<td valign="top">Pretty good composition, too bad the image suffers from too much noise, did you try to despeckle in PS?  Consider a tripod and lower ISO, and also straightening the windmill.</td>', 'Pretty good composition, too bad the image suffers from too much noise, did you try to despeckle in PS?  Consider a tripod and lower ISO, and also straightening the windmill.', '2006-11-04 01:23:01.000000', NULL, 1),
(2996809, 419358, 44490, '<td valign="top">Nice idea, I like the sailboats.  Consider cranking up saturation, brightness, and contrast, and a tighter crop may help, more detail on the boats would be better than too much soft sky.</td>', 'Nice idea, I like the sailboats.  Consider cranking up saturation, brightness, and contrast, and a tighter crop may help, more detail on the boats would be better than too much soft sky.', '2006-11-04 01:23:44.000000', NULL, 1),
(2996813, 418793, 39993, '<td valign="top">a beautiful big windblown bonzai.</td>', 'a beautiful big windblown bonzai.', '2006-11-04 01:24:43.000000', NULL, 1),
(2996821, 418286, 44490, '<td valign="top">This image makes a nice natural abstract, with a balance of sharpness and motion blur, light and dark, greens versus brighter colors.  Interesting, and I hope that others see it as well.</td>', 'This image makes a nice natural abstract, with a balance of sharpness and motion blur, light and dark, greens versus brighter colors.  Interesting, and I hope that others see it as well.', '2006-11-04 01:29:14.000000', NULL, 1),
(2996825, 418786, 44490, '<td valign="top">Interesting contrast of one side with leaves and bright colors, other side without leaves/color.  Nice DOF separation from background, more separation would be even better.</td>', 'Interesting contrast of one side with leaves and bright colors, other side without leaves/color.  Nice DOF separation from background, more separation would be even better.', '2006-11-04 01:33:00.000000', NULL, 1),
(2996827, 418443, 44490, '<td valign="top">Nice idea, more exposure on the face would help, and it looks like a pucker, but the flame is blowing in - confusing, maybe as intended?</td>', 'Nice idea, more exposure on the face would help, and it looks like a pucker, but the flame is blowing in - confusing, maybe as intended?', '2006-11-04 01:33:41.000000', NULL, 1),
(2996828, 419295, 44490, '<td valign="top">Good idea and nice try at a panning shot.  Just needs more clarity on the leaf and more blur on the rest - difficult to capture, kudos for the effort.</td>', 'Good idea and nice try at a panning shot.  Just needs more clarity on the leaf and more blur on the rest - difficult to capture, kudos for the effort.', '2006-11-04 01:34:00.000000', NULL, 1),
(2996832, 418999, 44490, '<td valign="top">Interesting tree, with growth shaped by prevailing winds, I assume.  A touch more contrast/saturation might help.</td>', 'Interesting tree, with growth shaped by prevailing winds, I assume.  A touch more contrast/saturation might help.', '2006-11-04 01:34:46.000000', NULL, 1),
(2996839, 418341, 44490, '<td valign="top">Nice pose and B&amp;W choice.  Some other evidence of wind would help, at least a leaf or two falling or moving, even if dropped by a person or blown by a fan.  As it is, it feels too posed.</td>', 'Nice pose and B&W choice.  Some other evidence of wind would help, at least a leaf or two falling or moving, even if dropped by a person or blown by a fan.  As it is, it feels too posed.', '2006-11-04 01:38:20.000000', NULL, 1),
(2996845, 418871, 44490, '<td valign="top">Nice idea.  Focus more toward foreground would help.  The tight packing of the row of headstones on the left might have made for better composition.</td>', 'Nice idea.  Focus more toward foreground would help.  The tight packing of the row of headstones on the left might have made for better composition.', '2006-11-04 01:41:31.000000', NULL, 1),
(2996848, 417618, 44490, '<td valign="top">Nice idea.  Eyes almost always are better.  The shawl is lost against the water, somehow held against her hair might give some needed contrast.</td>', 'Nice idea.  Eyes almost always are better.  The shawl is lost against the water, somehow held against her hair might give some needed contrast.', '2006-11-04 01:43:54.000000', NULL, 1),
(2996853, 417320, 44490, '<td valign="top">Nice idea.  Unfortunately the shadows are soft against the sand, and the image needs something more, maybe a wet spot, or something sharper like a sand dollar.</td>', 'Nice idea.  Unfortunately the shadows are soft against the sand, and the image needs something more, maybe a wet spot, or something sharper like a sand dollar.', '2006-11-04 01:48:43.000000', NULL, 1),
(2996855, 419181, 39993, '<td valign="top">never thought a windmill can look like a cd disk :)  I like it.</td>', 'never thought a windmill can look like a cd disk :)  I like it.', '2006-11-04 01:50:56.000000', NULL, 1),
(2996860, 418890, 39993, '<td valign="top">Hahaha, very windy indeed.</td>', 'Hahaha, very windy indeed.', '2006-11-04 01:53:08.000000', NULL, 1),
(2996875, 418160, 44490, '<td valign="top">Nice seascape, clouds, sky, waves, shoreline.  Image looks quite noisy, try lower ISO, a tripod, and/or despeckle in PS.</td>', 'Nice seascape, clouds, sky, waves, shoreline.  Image looks quite noisy, try lower ISO, a tripod, and/or despeckle in PS.', '2006-11-04 02:04:24.000000', NULL, 1),
(2996882, 419319, 44490, '<td valign="top">Nice waves and spray, but please do straighten the light-house!</td>', 'Nice waves and spray, but please do straighten the light-house!', '2006-11-04 02:08:32.000000', NULL, 1),
(2996885, 418621, 44490, '<td valign="top">Interesting lighting and shadows - wish for more eyes/face, even on a horse.</td>', 'Interesting lighting and shadows - wish for more eyes/face, even on a horse.', '2006-11-04 02:10:06.000000', NULL, 1),
(2996899, 418571, 44490, '<td valign="top">Nice idea, pose, and contasting colors.  But the expression is so pained, the brick wall is so dominant, and the lighting so hard and artificial.  Try a different (plainer) backdrop, or at least move Larry away from the wall, and use a photo umbrella or other diffuser.</td>', 'Nice idea, pose, and contasting colors.  But the expression is so pained, the brick wall is so dominant, and the lighting so hard and artificial.  Try a different (plainer) backdrop, or at least move Larry away from the wall, and use a photo umbrella or other diffuser.', '2006-11-04 02:13:53.000000', NULL, 1),
(2996910, 419258, 44490, '<td valign="top">Nice idea.  I''m not quite convinced, a few leaves in motion might help.  Shallower DOF would help tone down the distracting background.</td>', 'Nice idea.  I''m not quite convinced, a few leaves in motion might help.  Shallower DOF would help tone down the distracting background.', '2006-11-04 02:16:22.000000', NULL, 1),
(2996936, 417381, 44490, '<td valign="top">Interesting image seems to have captured some enchanted trees, probably due to the motion of the leaves - hope other viewers catch it.  A main subject would help, how about a fairy/nymph/etc?</td>', 'Interesting image seems to have captured some enchanted trees, probably due to the motion of the leaves - hope other viewers catch it.  A main subject would help, how about a fairy/nymph/etc?', '2006-11-04 02:30:15.000000', NULL, 1),
(2996939, 417581, 44490, '<td valign="top">Nice colors on ground, curving road, and bending trees.  Wish that there were some leaves falling, a few days or a week earlier would have helped, and perhaps a touch more contrast.</td>', 'Nice colors on ground, curving road, and bending trees.  Wish that there were some leaves falling, a few days or a week earlier would have helped, and perhaps a touch more contrast.', '2006-11-04 02:31:36.000000', NULL, 1),
(2996946, 419393, 66515, '<td valign="top">DNMC</td>', 'DNMC', '2006-11-04 02:34:46.000000', NULL, 1),
(2996965, 418815, 44490, '<td valign="top">Nice idea, I like the motion blur of the leaves and the pose of the woman with the umbrella.  Too bad a leaf obscures her face, seeing her face would really make the shot.  Looks like backfocus, consider trying manual focus with all this movement.</td>', 'Nice idea, I like the motion blur of the leaves and the pose of the woman with the umbrella.  Too bad a leaf obscures her face, seeing her face would really make the shot.  Looks like backfocus, consider trying manual focus with all this movement.', '2006-11-04 02:45:28.000000', NULL, 1),
(2997024, 418375, 44490, '<td valign="top">Good idea, nice color and texture.  Just needs something more, maybe a nose, eye/s, a hand with blowing a kiss?</td>', 'Good idea, nice color and texture.  Just needs something more, maybe a nose, eye/s, a hand with blowing a kiss?', '2006-11-04 03:35:07.000000', NULL, 1),
(2997034, 418499, 44490, '<td valign="top">Nice idea, wish for a complete shadow, and more saturation might help.</td>', 'Nice idea, wish for a complete shadow, and more saturation might help.', '2006-11-04 03:39:27.000000', NULL, 1),
(2997074, 419121, 44490, '<td valign="top">Nice lines, wish for a perspective and/or crop to get rid of the chain-link fence.  DOF to include both heads would help.</td>', 'Nice lines, wish for a perspective and/or crop to get rid of the chain-link fence.  DOF to include both heads would help.', '2006-11-04 04:00:40.000000', NULL, 1),
(2997078, 419362, 44490, '<td valign="top">Nice idea and wind-blow cape/cloth.  Lack of visible face/eyes pushes me to the buildings in the background.  I think that face/eyes and shallower DOF would help, along with elimination of the brush in the foreground.</td>', 'Nice idea and wind-blow cape/cloth.  Lack of visible face/eyes pushes me to the buildings in the background.  I think that face/eyes and shallower DOF would help, along with elimination of the brush in the foreground.', '2006-11-04 04:18:12.000000', NULL, 1),
(2997113, 419066, 44490, '<td valign="top">What a flock - there are so many, I don''t know where to look.  A tighter crop with fewer might be better and less busy, or some additional clear subject may help as a resting place for the eyes.</td>', 'What a flock - there are so many, I don''t know where to look.  A tighter crop with fewer might be better and less busy, or some additional clear subject may help as a resting place for the eyes.', '2006-11-04 04:40:26.000000', NULL, 1),
(2997115, 417041, 45475, '<td valign="top">While it is a great concept and set up, I find the post work to be over the top. This could have been so much more with less. Having said that though, I''m almost certain this style would appeal to many DPCers and I predict a good result for you :)</td>', 'While it is a great concept and set up, I find the post work to be over the top. This could have been so much more with less. Having said that though, I''m almost certain this style would appeal to many DPCers and I predict a good result for you :)', '2006-11-04 04:40:59.000000', NULL, 1),
