(2997120, 418521, 45475, '<td valign="top">Dramatic shot, well captured. Bet this looks awesome at full size.</td>', 'Dramatic shot, well captured. Bet this looks awesome at full size.', '2006-11-04 04:42:31.000000', NULL, 1),
(2997121, 419178, 45475, '<td valign="top">Nice, this would make a mad poster!</td>', 'Nice, this would make a mad poster!', '2006-11-04 04:42:46.000000', NULL, 1),
(2997122, 418435, 44490, '<td valign="top">Nice combination of the soft curves of the grasses against the harder lines of the church, plus interesting lighting.  I think a slightly higher perspective might help with grasses lower and less obscuring of the windows.</td>', 'Nice combination of the soft curves of the grasses against the harder lines of the church, plus interesting lighting.  I think a slightly higher perspective might help with grasses lower and less obscuring of the windows.', '2006-11-04 04:42:54.000000', NULL, 1),
(2997123, 417415, 44490, '<td valign="top">Love the laughter and blowing hair.  Wish for a little more eye/s.  Captivating expression.</td>', 'Love the laughter and blowing hair.  Wish for a little more eye/s.  Captivating expression.', '2006-11-04 04:43:04.000000', NULL, 1),
(2997124, 418949, 45475, '<td valign="top">Great colour and comp. Cool flag shot :)</td>', 'Great colour and comp. Cool flag shot :)', '2006-11-04 04:43:12.000000', NULL, 1),
(2997126, 417899, 45475, '<td valign="top">Awesome view. Good depth and drama. Cropping out the foreground water wouldn''t hurt, I don''t think. Have you tried this in b&amp;w? Bet it would look great.</td>', 'Awesome view. Good depth and drama. Cropping out the foreground water wouldn''t hurt, I don''t think. Have you tried this in b&w? Bet it would look great.', '2006-11-04 04:43:43.000000', NULL, 1),
(2997127, 419254, 44490, '<td valign="top">Lovely model, blue eyes, pose, lighting including fill, bokeh, strands of hair across forehead and neck.  Needs a little more wind effect, breeze-blown garments might help.  Nicely done.</td>', 'Lovely model, blue eyes, pose, lighting including fill, bokeh, strands of hair across forehead and neck.  Needs a little more wind effect, breeze-blown garments might help.  Nicely done.', '2006-11-04 04:43:51.000000', NULL, 1),
(2997128, 418452, 44490, '<td valign="top">Looks like the USS Olympia, and way to work the North Wind in so prominently - just wish that it had a sail up to match.  Interesting lines.</td>', 'Looks like the USS Olympia, and way to work the North Wind in so prominently - just wish that it had a sail up to match.  Interesting lines.', '2006-11-04 04:43:56.000000', NULL, 1),
(2997130, 419344, 45475, '<td valign="top">Excellent idea. Very dizzying too. Well done.</td>', 'Excellent idea. Very dizzying too. Well done.', '2006-11-04 04:44:03.000000', NULL, 1),
(2997131, 418949, 44490, '<td valign="top">Nice capture of different positions for the row of similar flags, nice colors, simple and effective, and captures the feel for the wind.</td>', 'Nice capture of different positions for the row of similar flags, nice colors, simple and effective, and captures the feel for the wind.', '2006-11-04 04:44:09.000000', NULL, 1),
(2997133, 418891, 45475, '<td valign="top">Can hear the wind howling in this shot. Very well done.</td>', 'Can hear the wind howling in this shot. Very well done.', '2006-11-04 04:44:14.000000', NULL, 1),
(2997134, 419254, 45475, '<td valign="top">Clean and fresh. Good use of natural (back)light and a wonderful example of a gentle breeze.</td>', 'Clean and fresh. Good use of natural (back)light and a wonderful example of a gentle breeze.', '2006-11-04 04:44:20.000000', NULL, 1),
(2997135, 418966, 44490, '<td valign="top">Nice combination of the tree in the wind and the branch covered building.  B&amp;W works great here for the challenge.</td>', 'Nice combination of the tree in the wind and the branch covered building.  B&W works great here for the challenge.', '2006-11-04 04:44:22.000000', NULL, 1),
(2997136, 418623, 44490, '<td valign="top">Lovely sunset, I assume, colors, reflection, and pose, just wish that the model were closer, larger, more detailed.</td>', 'Lovely sunset, I assume, colors, reflection, and pose, just wish that the model were closer, larger, more detailed.', '2006-11-04 04:44:26.000000', NULL, 1),
(2997137, 419361, 45475, '<td valign="top">Ummm... I''m not really feeling the wind here, but I do like well taken toy shots :)</td>', 'Ummm... I''m not really feeling the wind here, but I do like well taken toy shots :)', '2006-11-04 04:44:29.000000', NULL, 1),
(2997139, 418521, 44490, '<td valign="top">Beautiful shot, capturing the crashing waves, golden sunset, and birds on wing.  Hope it does well.</td>', 'Beautiful shot, capturing the crashing waves, golden sunset, and birds on wing.  Hope it does well.', '2006-11-04 04:44:32.000000', NULL, 1),
(2997140, 418244, 44490, '<td valign="top">Lovely lines especially toward the wing-tips.  Wish for head and eyes, but the wing position and detail make the image.</td>', 'Lovely lines especially toward the wing-tips.  Wish for head and eyes, but the wing position and detail make the image.', '2006-11-04 04:44:41.000000', NULL, 1),
(2997141, 418815, 45475, '<td valign="top">Delightful, happy, fun shot! Just a pity the leaf obscures her face so, but ya can''t predict where those little buggers are going to fly :)</td>', 'Delightful, happy, fun shot! Just a pity the leaf obscures her face so, but ya can''t predict where those little buggers are going to fly :)', '2006-11-04 04:44:46.000000', NULL, 1),
(2997142, 418630, 44490, '<td valign="top">Nice idea, beautiful woman, colors, flowers, hair, DOF, bokeh.  The pose is good, but too bad her expression seems like she is freezing rather than enjoying the breeze.  I like the idea and overall feeling.</td>', 'Nice idea, beautiful woman, colors, flowers, hair, DOF, bokeh.  The pose is good, but too bad her expression seems like she is freezing rather than enjoying the breeze.  I like the idea and overall feeling.', '2006-11-04 04:44:53.000000', NULL, 1),
(2997147, 419258, 56672, '<td valign="top">Maybe if there were actual rain.<br/> <br/>This *might* have worked if it had been B&amp;W</td>', 'Maybe if there were actual rain. This *might* have worked if it had been B&W', '2006-11-04 04:45:21.000000', NULL, 1),
(2997148, 417447, 45475, '<td valign="top">Strange and very cool.</td>', 'Strange and very cool.', '2006-11-04 04:45:23.000000', NULL, 1),
(2997151, 419275, 44490, '<td valign="top">Nice positions of people and kite, nice colors of beach, sky, and kite.  Sky and waves look a little over-processed.  Wish that I had wind good enough to fly a kite.  Oh joy!</td>', 'Nice positions of people and kite, nice colors of beach, sky, and kite.  Sky and waves look a little over-processed.  Wish that I had wind good enough to fly a kite.  Oh joy!', '2006-11-04 04:46:43.000000', NULL, 1),
