(2997155, 417899, 44490, '<td valign="top">It almost gives the feeling of being there in the wind and spray - nice.  Cropping out the water in foreground might be better.</td>', 'It almost gives the feeling of being there in the wind and spray - nice.  Cropping out the water in foreground might be better.', '2006-11-04 04:46:56.000000', NULL, 1),
(2997168, 419380, 44490, '<td valign="top">Nice idea and execution.  Too cute to be dressed in black, but it works here - intriguing expression, nice wind-blown hair.</td>', 'Nice idea and execution.  Too cute to be dressed in black, but it works here - intriguing expression, nice wind-blown hair.', '2006-11-04 04:48:44.000000', NULL, 1),
(2997169, 418774, 44490, '<td valign="top">Flying high!  Nice formation, wish tail from kite out of frame wasn''t there.  Nice colors and composition.</td>', 'Flying high!  Nice formation, wish tail from kite out of frame wasn''t there.  Nice colors and composition.', '2006-11-04 04:48:48.000000', NULL, 1),
