INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3004469, 419141, 27133, '<td valign="top">Wow...this is simply stunning.  I didn''t get to vote on Wind...but this would definitely have been a 10.  Congrats Rudy.</td>', 'Wow...this is simply stunning.  I didn''t get to vote on Wind...but this would definitely have been a 10.  Congrats Rudy.', '2006-11-06 00:40:48.000000', NULL, 0),
(3004476, 417831, 33352, '<td valign="top">Good one Judi, Voted an eight on this, thought would have finished higher, Kita has shot up of late and her hair is longer.</td>', 'Good one Judi, Voted an eight on this, thought would have finished higher, Kita has shot up of late and her hair is longer.', '2006-11-06 00:42:27.000000', NULL, 0),
(3004484, 419019, 33352, '<td valign="top">Got a 5 from me as I thought it was cute.</td>', 'Got a 5 from me as I thought it was cute.', '2006-11-06 00:44:57.000000', NULL, 0),
(3004485, 417831, 36988, '<td valign="top">Beautifully done Judi. She''s like a miniature you but not so small anymore. :)</td>', 'Beautifully done Judi. She''s like a miniature you but not so small anymore. :)', '2006-11-06 00:45:10.000000', NULL, 0),
(3004487, 419298, 6349, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by glad2badad:</b></div><hr/><i> The impression of a windy day is quite evident in your photo.  Well done in that regard.  The combination of seagulls in the wind and the waves coming in make a strong connection to the challenge.  Technically, you''re a bit blown out in the highlights, some flare is making the shoreline hazy in the distance (UV/Polarizer may have helped some along with a lens hood, even a hat).  The biggest thing that is going to zap you on this is the slanted horizon.  That just drives many photographers on this site crazy!  :D  Unfortunately it''s slanted enough that it''s evident to even the casual viewer.  All of the above is JMO of course.  Wish you luck in the challenge. </i></td></tr></table> <br/> <br/>Man, it wasn''t until I got this comment that I realized I had uploaded the wrong photo to the challenge.  I had one where it was rotated correctly with a slightly better crop.  Looking at them side by side it makes all the difference.  As far as the lighting, I was shooting pretty much directly at the sun and in the original the foreground is extremely dark.  This made for the interesting light in the photo and the lenses I had wouldn''t have helped this.  A gradient ND filter would have been good.</td>', 'Originally posted by glad2badad: The impression of a windy day is quite evident in your photo.  Well done in that regard.  The combination of seagulls in the wind and the waves coming in make a strong connection to the challenge.  Technically, you''re a bit blown out in the highlights, some flare is making the shoreline hazy in the distance (UV/Polarizer may have helped some along with a lens hood, even a hat).  The biggest thing that is going to zap you on this is the slanted horizon.  That just drives many photographers on this site crazy!  :D  Unfortunately it''s slanted enough that it''s evident to even the casual viewer.  All of the above is JMO of course.  Wish you luck in the challenge.   Man, it wasn''t until I got this comment that I realized I had uploaded the wrong photo to the challenge.  I had one where it was rotated correctly with a slightly better crop.  Looking at them side by side it makes all the difference.  As far as the lighting, I was shooting pretty much directly at the sun and in the original the foreground is extremely dark.  This made for the interesting light in the photo and the lenses I had wouldn''t have helped this.  A gradient ND filter would have been good.', '2006-11-06 00:46:19.000000', NULL, 0),
(3004488, 418521, 37648, '<td valign="top">Congratulations! Epic shot dude, sharp shooting</td>', 'Congratulations! Epic shot dude, sharp shooting', '2006-11-06 00:46:24.000000', NULL, 0),
