(3005918, 418521, 50531, '<td valign="top">Yeah congrats very nice</td>', 'Yeah congrats very nice', '2006-11-06 11:59:35.000000', NULL, 0),
(3005936, 419298, 50695, '<td valign="top">I have a feeling it was a blessed mistake. I gave this photo a 10. I couldn''t possibly tell you why this photo feels like wind, more than any other photo in the competition, but "fixing" it, even the tilt of the horizon, could endanger that feeling. I''d be very curious to see your fixed version.</td>', 'I have a feeling it was a blessed mistake. I gave this photo a 10. I couldn''t possibly tell you why this photo feels like wind, more than any other photo in the competition, but "fixing" it, even the tilt of the horizon, could endanger that feeling. I''d be very curious to see your fixed version.', '2006-11-06 12:03:49.000000', NULL, 0),
(3005954, 418795, 14603, '<td valign="top">One of the best pics I`ve seen on here for some time.<br/>I love the contrasts...between the sharpness of the child and the softness of the bubbles and also the subdued background colour &amp; the irridescence again, in the bubbles.<br/>Quite superb.</td>', 'One of the best pics I`ve seen on here for some time.I love the contrasts...between the sharpness of the child and the softness of the bubbles and also the subdued background colour & the irridescence again, in the bubbles.Quite superb.', '2006-11-06 12:10:16.000000', NULL, 0),
