(3008000, 419299, 27482, '<td valign="top">No offense to the blue ribbon entry but this was the best shot in the challenge as far as I am concerned, love that texture of the sand, nice work, glad it ended up above me.</td>', 'No offense to the blue ribbon entry but this was the best shot in the challenge as far as I am concerned, love that texture of the sand, nice work, glad it ended up above me.', '2006-11-06 20:27:01.000000', NULL, 0),
